package pe.edu.upeu.casaonada.orden.api;
import pe.edu.upeu.casaonada.orden.domain.EstadoOrden; import pe.edu.upeu.casaonada.orden.dto.*; import pe.edu.upeu.casaonada.orden.service.OrdenService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @RequestMapping("/api/v1/ordenes") public class OrdenController { private final OrdenService s; public OrdenController(OrdenService s){this.s=s;} @PostMapping public ResponseEntity<OrdenResponse> crear(@Valid @RequestBody OrdenRequest r){var x=s.crear(r);return ResponseEntity.created(URI.create("/api/v1/ordenes/"+x.id())).body(x);} @GetMapping public List<OrdenResponse> listar(){return s.listar();} @GetMapping("/{id}") public OrdenResponse buscar(@PathVariable Long id){return s.buscar(id);} @PatchMapping("/{id}/estado") public OrdenResponse estado(@PathVariable Long id,@RequestBody Map<String,String> b){return s.cambiarEstado(id,EstadoOrden.valueOf(b.get("estado")));} }
